import { Box, Grid, Typography, Divider, Tooltip } from "@mui/material";

import React from "react";
import { useEffect } from "react";
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import FallbackSpinner from "src/@core/components/spinner";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError } from "src/utils/utils";

const ITSolutionDropDown = () => {
  const [loading, setLoading] = useState(false);
  const [itSolutions, setItSolutions] = useState([]);
  const [subItSolutions, setSubItSolutions] = useState([]);
  const [subItSolutionsLists, setSubItSolutionsLists] = useState([]); // Store multiple sub-lists dynamically
  const navigate = useNavigate();
  const [activeITSolutionId, setActiveITSolutionId] = useState(null);

  const fetchITSoltionsData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTIONS.list)
      .then((response) => {
        const responseData = response.data.data;
        setItSolutions(response.data.data);

        if (responseData.length > 0) {
          fetchSubITSoltionsData(responseData[0].id); // Get the id of the first IT solution
          setActiveITSolutionId(responseData[0].id); // Get the id of the first IT solution
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchSubITSoltionsData = (id) => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.SUB_IT_SOLUTIONS.list(id))
      .then((response) => {
        setSubItSolutions(response.data.data);
        const responseData = response.data.data;
        if (responseData) {
          responseData.forEach((item, index) => {
            fetchSubITSoltionsList(item.id, index);
          });
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchSubITSoltionsList = (id, index) => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.SUB_IT_SOLUTIONS_LIST.list(id))
      .then((response) => {
        setSubItSolutionsLists((prevState) => {
          const newState = [...prevState];
          newState[index] = response.data.data; // Store each sub-list at its respective index
          return newState;
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  // On component mount, fetch the main IT solutions and sub IT solutions for default ID 13
  useEffect(() => {
    fetchITSoltionsData();
  }, []);

  // Function to handle main IT solution clicks and fetch its sub IT solutions
  const handleITSolutionClick = (id, event) => {
    event.stopPropagation();
    fetchSubITSoltionsData(id);
    setActiveITSolutionId(id);
  };

  // Reusable function to handle clicks on sub IT solutions and navigate to the detail page
  const handleSubItSolutionClick = (index, subITSolutionId) => {
    if (subITSolutionId) {
      localStorage.setItem("ITSolutionId", subITSolutionId);
    }
    navigate(`/it-solution-overview/${subITSolutionId}`);
  };

  return (
    <>
      <Box sx={{ width: "1280px", px: 10, py: 5 }}>
        <Grid container spacing={12}>
          <Grid
            item
            xs={4}
            sx={{ display: "flex", flexDirection: "column", gap: 5 }}
          >
            <Typography
              sx={{
                fontSize: { lg: "24px" },
                lineHeight: { lg: "32px" },
                fontWeight: 600,
                color: "#602DE1",
              }}
            >
              IT Solutions
            </Typography>
            <Box
              sx={{ pl: 5, display: "flex", flexDirection: "column", gap: 7 }}
            >
              {itSolutions?.map((item, index) => (
                <Typography
                  onClick={(event) => handleITSolutionClick(item.id, event)}
                  key={index}
                  sx={{
                    fontSize: { lg: "16px" },
                    lineHeight: { lg: "24px" },
                    fontWeight: 600,
                    textWrap: "wrap",
                    color:
                      activeITSolutionId === item.id ? "#602DE1" : "#101828",
                    "&:hover": {
                      color: "#602DE1",
                    },
                    cursor: "pointer",
                  }}
                >
                  {item.title}
                </Typography>
                // <Typography
                //   onClick={(event) => handleITSolutionClick(item.id, event)}
                //   key={index}
                //   sx={{
                //     fontSize: { lg: "16px" },
                //     lineHeight: { lg: "24px" },
                //     fontWeight: 600,
                //     color:
                //       activeITSolutionId === item.id ? "#602DE1" : "#101828",
                //     "&:hover": {
                //       color: "#602DE1",
                //     },
                //     cursor: "pointer",
                //     textWrap: "wrap",
                //   }}
                // >
                //   {/* {item.title.length > 40 ? (
                //     <Tooltip title={item.title} arrow>
                //       <span>{`${item.title.slice(0, 40)}...`}</span>
                //     </Tooltip>
                //   ) : (
                //     <span>{item.title}</span>
                //   )} */}
                //   {item.title}
                // </Typography>
              ))}
            </Box>
          </Grid>
          <Grid item container xs={8} columnSpacing={10}>
            {/* <Grid container spacing={8}> */}
            {subItSolutions?.map((item, index) => (
              <Grid item xs={12} sm={6} md={4} key={index}>
                <Box sx={{ mb: 3 }}>
                  <Typography
                    sx={{
                      fontSize: { lg: "16px" },
                      lineHeight: { lg: "24px" },
                      fontWeight: 600,
                      color: "#602DE1",
                      mb: 1,
                      // textWrap: "wrap",
                      wordWrap: "break-word",
                      whiteSpace: "normal",
                    }}
                  >
                    {/* {item.title.length > 50 ? (
                      <Tooltip title={item.title} arrow>
                        <span>{`${item.title.slice(0, 50)}...`}</span>
                      </Tooltip>
                    ) : (
                      <span>{item.title}</span>
                    )} */}
                    {item.title}
                  </Typography>

                  <Typography
                    sx={{
                      fontSize: { lg: "14px" },
                      lineHeight: { lg: "20px" },
                      fontWeight: 400,
                      color: "#667085",
                      mb: 2,
                      textWrap: "wrap",
                    }}
                  >
                    {/* {item.description.length > 75 ? (
                      <Tooltip
                        title={
                          <div
                            dangerouslySetInnerHTML={{
                              __html: item.description,
                            }}
                          />
                        }
                        arrow
                      >
                        <div
                          dangerouslySetInnerHTML={{
                            __html: `<style>p { margin: 0; }</style>${item.description.slice(
                              0,
                              75
                            )}...`,
                          }}
                        />
                      </Tooltip>
                    ) : (
                      <div
                        dangerouslySetInnerHTML={{
                          __html: `<style>p { margin: 0; }</style>${item.description}`,
                        }}
                      />
                    )} */}
                    <div
                      style={{
                        wordWrap: "break-word",
                        whiteSpace: "normal",
                      }}
                      dangerouslySetInnerHTML={{
                        __html: `<style>p { margin: 0; }</style>${item.description}`,
                      }}
                    />
                  </Typography>
                </Box>

                <Box sx={{ mb: 5 }}>
                  <Divider sx={{ width: "50%", borderWidth: "1px" }} />
                </Box>
                {/* Sub-data under the title */}
                {subItSolutionsLists[index]?.map((subItem, subIndex) => (
                  <Box
                    key={subIndex}
                    onClick={() =>
                      handleSubItSolutionClick(subIndex, subItem.id)
                    }
                    sx={{ mb: 10 }}
                  >
                    <Typography
                      sx={{
                        fontSize: { lg: "16px" },
                        lineHeight: { lg: "24px" },
                        fontWeight: 500,
                        color: "#101828",
                        textWrap: "wrap",
                        "&:hover": {
                          color: "#602DE1",
                          cursor: "pointer",
                        },
                        mb: 1,
                      }}
                    >
                      {/* {subItem.title.length > 25 ? (
                        <Tooltip title={subItem.title} arrow>
                          <span>{`${subItem.title.slice(0, 25)}...`}</span>
                        </Tooltip>
                      ) : (
                        <span>{subItem.title}</span>
                      )} */}
                      {subItem.title}
                    </Typography>
                    <Typography
                      sx={{
                        fontSize: { lg: "14px" },
                        lineHeight: { lg: "20px" },
                        fontWeight: 400,
                        color: "#667085",
                        textWrap: "wrap",
                      }}
                    >
                      {/* {subItem.description.length > 70 ? (
                        <Tooltip
                          title={
                            <div
                              dangerouslySetInnerHTML={{
                                __html: subItem.description,
                              }}
                            />
                          }
                          arrow
                        >
                          <div
                            dangerouslySetInnerHTML={{
                              __html: `<style>p { margin: 0; }</style>${subItem.description.slice(
                                0,
                                70
                              )}...`,
                            }}
                          />
                        </Tooltip>
                      ) : (
                        <div
                          dangerouslySetInnerHTML={{
                            __html: `<style>p { margin: 0; }</style>${subItem.description}`,
                          }}
                        />
                      )} */}
                      <div
                        dangerouslySetInnerHTML={{
                          __html: `<style>p { margin: 0; }</style>${subItem.description}`,
                        }}
                      />
                    </Typography>
                  </Box>
                ))}
              </Grid>
            ))}
            {/* </Grid> */}
          </Grid>
        </Grid>
      </Box>
    </>
  );
};

export default ITSolutionDropDown;
